custom_defined_behaviors:
   behaviors {
       td_symbols: td_symbols {
       compatible = "zmk,behavior-tap-dance";
       label = "SYM_TAP_DANCE";
       #binding-cells = <0>;
       tapping-term-ms = <200>;
       bindings = <&sl LAYER_Symbols>, <&sl LAYER_AutoPairs>;
       };

       hyper_dance: hyper_dance {
           compatible = "zmk,behavior-tap-dance";
           label = "HYPER_DANCE";
           #binding-cells = <0>;
           tapping-term-ms = <250>;
           bindings = <&sk LA(LC(LGUI))>, <&sk LS(LA(LC(LGUI)))>;
       };

       hyper_shift_dance: hyper_shift_dance {
           compatible = "zmk,behavior-tap-dance";
           label = "HYPER_SHIFT_DANCE";
           #binding-cells = <0>;
           tapping-term-ms = <250>;
           bindings = <&sk LS(LA(LC(LGUI)))>, <&sk LS(LA(LC(LGUI)))>;
       };

       colons_dance: colons_dance {
           compatible = "zmk,behavior-mod-morph";
           label = "COLONS_DANCE";
           #binding-cells = <0>;
           bindings = <&kp COLON>, <&kp SEMI>;
           mods = <(MOD_LSFT|MOD_RSFT)>;
   };

       hrm: hrm {
           compatible = "zmk,behavior-hold-tap";
           label = "HOME_ROW_MODS";
           #binding-cells = <2>;
           tapping-term-ms = <280>;
           quick-tap-ms = <175>;
           require-prior-idle-ms = <150>;
           flavor = "balanced";
           bindings = <&kp>, <&kp>;
       };

   // Macro for Ctrl + Shift + C
   rsi_copy: rsi_copy {
       compatible = "zmk,behavior-macro";
       #binding-cells = <0>;
       bindings = <&macro_press &kp LCTRL &kp LSHFT>, 
                  <&macro_tap &kp C>, 
                  <&macro_release &kp LCTRL &kp LSHFT>;
   };

   // Macro for Ctrl + Shift + V
   rsi_paste: rsi_paste {
       compatible = "zmk,behavior-macro";
       #binding-cells = <0>;
       bindings = <&macro_press &kp LCTRL &kp LSHFT>, 
                  <&macro_tap &kp V>, 
                  <&macro_release &kp LCTRL &kp LSHFT>;
   };

};
